<include file="Public:header"/><style>    .frame_form td{line-height:24px;}</style><table cellpadding="0" cellspacing="0" class="frame_form" width="100%">    <tr>        <th width="15%">订单编号</th>        <td colspan="3" width="85%">{pigcms{$now_order.order_id}</td>    </tr>    <if condition="$now_order.orderid neq 0">        <tr>            <th width="15%">订单流水号</th>            <td colspan="3" width="85%">{pigcms{$now_order.orderid}</td>        </tr>    </if>    <tr>        <th width="15%">礼包名称</th>        <td colspan="3" width="85%">{pigcms{$now_order.gift_name}</td>    </tr>    <tr>        <th width="15%">订单状态</th>        <td colspan="3" width="85%">{pigcms{$order_status[$now_order['status']]}</td>    </tr>    <tr>        <if  condition="$now_order['status'] gt 0 && $now_order['get_time']">            <th width="15%">领取时间</th>            <td width="35%">{pigcms{$now_order.get_time|date='Y-m-d H:i:s',###}</td>            <else/>            <th width="15%">记录时间</th>            <td width="35%">{pigcms{$now_order.add_time|date='Y-m-d H:i:s',###}</td>        </if>        <if condition="$now_order['status'] gt 1 && $now_order['send_time']">            <th width="15%">发货时间</th>            <td width="35%">{pigcms{$now_order.send_time|date='Y-m-d H:i:s',###}</td>            <else/>            <th width="15%"></th>            <td width="35%"></td>        </if>    </tr>    <tr>        <th width="15%">买家留言</th>        <td width="85%" colspan="3">{pigcms{$now_order.get_remark}</td>    </tr>    <if condition="$now_order['uid']">        <tr>            <td colspan="4" style="padding-left:5px;color:black;"><b>用户信息：</b></td>        </tr>        <tr>            <th width="15%">用户ID</th>            <td width="35%">{pigcms{$now_order.uid}</td>            <th width="15%">领取者名称</th>            <td width="35%">{pigcms{$now_order.get_name}</td>        </tr>        <tr>            <th width="15%">领取者手机号</th>            <td width="35%">{pigcms{$now_order.get_phone}</td>            <th width="15%">领取者地址</th>            <td width="35%">{pigcms{$now_order.get_address}</td>        </tr>        <php>if ($now_user) {</php>            <tr>                <th width="15%">注册昵称</th>                <td width="35%">{pigcms{$now_user.nickname|default='-'}</td>                <th width="15%">注册手机号</th>                <td width="35%">{pigcms{$now_user.phone|default='-'}</td>            </tr>        <php>}</php>    </if>        <tr>            <th width="15%">快递信息</th>            <td width="85%" colspan="3">                <select id="express_id">                    <volist name="express_list" id="vo">                        <option value="{pigcms{$vo.id}" <if condition='$vo["id"] eq $now_order["express_id"]'>selected="selected"</if>>{pigcms{$vo.name}</option>                    </volist>                </select>                <input type="text" class="input" id="express_number" value="{pigcms{$now_order.express_number}" style="width:140px;"/>                <button id="express_id_btn">填写</button></td>        </tr>    </if></table><div class="btn hidden">    <input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />    <input type="reset" value="取消" class="button" /></div><script type="text/javascript" language="javascript">    $('#express_id_btn').click(function(){        if(confirm("您确定要提交快递信息吗？提交后订单状态会修改为已发货。")){            express_post();        }    });    function express_post(){        $('#express_id_btn').html('提交中...').prop('disabled',true);        $.post("{pigcms{:U('level_gift_express',array('order_id'=>$now_order['order_id']))}",{express_number:$('#express_number').val(),express_id:$('#express_id').val()},function(result){            if(result.status == 1){                window.location.href = window.location.href;            }            $('#express_id_btn').html('填写').prop('disabled',false);            alert(result.info);        });    }</script><include file="Public:footer"/>